#!/usr/bin/env python3
"""Run every reconstruction gate before a commit; exit non-zero if any fails.

  boot leaves      gate_boot_leaves.py            (all verified bootstrap leaves)
  component ABI    gate_game_component_abi.py
  native GFMain    gate_native_gfmain.py (machine code and simulated-call execution)
  window messages gate_window_messages.py (compiled fixture and retail comparison)
  critical dialog gate_critical_message.py (relocations and mocked dialog fixture)
  input focus     gate_input_focus.py (device callbacks and retail comparison)
  exclusive mode  gate_exclusive_mode.py (mode attempts and retail comparison)
  init window     gate_init_window.py (window setup and retail comparison)
  activation      gate_system_activation.py (focus/sound and retail comparison)
  sound enabled   gate_sound_enabled.py (corrected owner and linked fixture)
  window callback gate_window_procedure.py (code, dispatch tables and retail cases)
  window leaves   gate_window_leaves.py (active/focus setters and character ring)
  gamma ramp      gate_set_gamma.py (ramp, floating-point modes and mocked D3D)
  app name        gate_application_name.py (command parsing and string lifetimes)
  system colours  gate_system_colours.py (palette calls and shared layout)
  system shutdown gate_system_shutdown.py (release order and callback mutation)
  system lifetime gate_system_lifetime.py (construction and destruction)
  system update   gate_system_update.py (shared sound ABI and callback state)
  reset callbacks gate_device_reset_callbacks.py (list ownership and registration)
  reset phases    gate_device_reset_phases.py (ordered dispatch and callback ABIs)
  render core     gate_render_core_reset.py (device setup and font cleanup)
  timer cleanup   gate_timer_clear.py (query release order and list mutation)
  timer lifetime  gate_timer_lifetime.py (sentinel allocation and destruction)
  render state    gate_render_state_init.py (state reset and callee ordering)
  header deps      gate_header_dependents.py --rev REV   (0 regressions required)
  bootstrap refs   every src/tests path build_bootstrap.ps1 names exists
  ring             rebuild/runtime/openretailbank/link_smoke.py (0 unresolved)
  bootstrap        rebuild/build_bootstrap.ps1 (only with --bootstrap; ~10 minutes)

Usage: python tools/decomp_pipeline/gate_all.py [--rev land/boot-debake] [--bootstrap]
"""
import argparse
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PY = sys.executable


def run(name, cmd, ok):
    proc = subprocess.run(cmd, cwd=ROOT, capture_output=True, text=True)
    out = proc.stdout + proc.stderr
    passed = proc.returncode == 0 and ok(out)
    tail = out.strip().splitlines()[-1] if out.strip() else ""
    print(f"{'PASS' if passed else 'FAIL'}  {name:14} {tail[:120]}")
    if not passed:
        lines = out.strip().splitlines()
        # Keep the failing leaf and its diagnostics visible even when later
        # passing leaves would otherwise push it out of the final 15 lines.
        failures = [i for i, line in enumerate(lines)
                    if re.search(r"\b(?:GATE_FAIL|LINK_FAIL|TCC_FAIL|SRC_FAIL|FAIL|TIMEOUT|REGRESSION)\b", line)]
        selected = set(range(max(0, len(lines) - 15), len(lines)))
        for i in failures:
            selected.update(range(max(0, i - 1), min(len(lines), i + 5)))
        print("\n".join("      " + lines[i] for i in sorted(selected)))
    return passed


def bootstrap_refs():
    text = (ROOT / "rebuild/build_bootstrap.ps1").read_text(encoding="utf-8", errors="replace")
    missing = [rel for rel in sorted(set(re.findall(r"'((?:src|tests)\\[^']+\.cpp)'", text)))
               if not (ROOT / "rebuild" / rel.replace("\\", "/")).is_file()]
    print(f"{'PASS' if not missing else 'FAIL'}  {'bootstrap refs':14} {len(missing)} missing")
    for rel in missing:
        print("      missing", rel)
    return not missing


