    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--rev", default="land/boot-debake")
    ap.add_argument("--bootstrap", action="store_true")
    ap.add_argument("--gpu", action="store_true", help="Include real-device retail-title raster validation")
